function notifications(){const items=[];const exp=state.gpoSession?.expiresAt?new Date(state.gpoSession.expiresAt):null,mins=exp?Math.max(0,Math.ceil((exp-Date.now())/60000)):null;if(mins!=null&&mins<=5)items.push([say('Sessiya bitir','Session expiring'),say(`Delegated AD sessiyası ${mins} dəqiqəyə bitir.`,`Delegated AD session expires in ${mins} minute(s).`)]);if(state.session?.mode!=='WINDOWS')items.push([say('Windows / AD aktiv deyil','Windows / AD inactive'),say('Control Center və ya bu səhifədən Windows / AD rejimini başladın.','Start Windows / AD mode from Control Center or this page.')]);if(!state.inventory)items.push(['AD not connected','Connect before generating a real remediation plan.']);const review=state.history.filter(h=>/FAIL|REVIEW|PARTIAL|DRIFT|MISMATCH/.test(String(h.result?.state||'').toUpperCase())).length;if(review)items.push(['Operations need review',`${review} operation(s) require attention.`]);if(state.readiness&&!state.readiness.ready)items.push(['Environment needs attention','One or more required backend readiness checks did not pass.']);return items;}
