function busyLayer(){return state.busy?`<div class="busy-layer" role="status" aria-live="polite"><div class="busy-card"><span class="busy-spinner"></span><div><strong>${say('Sorğu icra olunur','Processing request')}</strong><small data-request-progress>${say('Bu pəncərəni açıq saxlayın.','Keep this window open.')}</small><button type="button" data-cancel-request hidden>${say('Gözləməyi dayandır','Stop waiting')}</button></div></div></div>`:'';}
let catalogRenderTimer;
